from IPython.display import Image, display
# Optional original diagram assets from the accompanying repository bundle.
DIAGRAM_DIR = Path(os.environ.get("GEMMA_REFERENCE_DIAGRAMS", "/kaggle/input/gemma-reference-tools/diagrams_r2"))
for name in ("reference_pipeline.png", "evaluation_contract.png", "cost_and_promotion.png"):
    asset = DIAGRAM_DIR / name
    if asset.is_file():
        display(Image(filename=str(asset)))
    else:
        print(f"Set GEMMA_REFERENCE_DIAGRAMS to the directory containing the three PNG assets (public/diagrams_r2) to display {name}.")
